            if gcd not in seen_gcds:
                if is_unit_gcd(queue) and gcd == 1 and queue[0] // gcd != A[i] // gcd:
                    return -1
                seen_gcds.add(gcd)
                queue.insert(0, A[i])
            else:
                return -1
    return N - len(queue)

