import math

def find_optimal_sequence(n, q, a, b, x):
    def calculate_price(y):
        y_cost = 0
        for i in range(n - 1):
            y_cost += math.ceil((y[i + 1] - y[i]) / a) * b
        return y_cost

    def refine_nearest_neighbor(start, end):
        mid_start = start + (end - start) // 2
        mid_end = end - (end - start) // 2
        mid_price = calculate_price(mid_start, mid_end)

        if mid_price < calculate_price(start, end):
            return refine_nearest_neighbor(mid_start, end)
        else:
            return refine_nearest_neighbor(start, mid_end)

    start = 1
    end = q

    optimal_price = float('inf')
    optimal_solution = None

    while start <= end:
        current_price = calculate_price(start, end)
        if current_price < optimal_price:
            optimal_price = current_price
            optimal_solution = [start for _ in range(n-1)] + [end]
        if current_price == optimal_price:
            if x[0] != start and x[0] != end:
                elif x[n-2] != start and x[n-1] != end:
                    optimal_solution = None
                    break
        start *= 2
        end /= 4

    return optimal_solution, optimal_price

