import math
from collections import Counter

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def apply_factorial_p(value, factor):
    return value * math.factorial(factor - 1)

def special_sum(subarray):
    product = math.prod(subarray)
    prime_factors_list = prime_factors(product)
    distinct_prime_factors_count = len(Counter(prime_factors_list)[prime_factors_list])
    return (sum(subarray) - apply_factorial_p(distinct_prime_factors_count, len(subarray))) * apply_factorial_p(distinct_prime_factors_count, len(subarray))

def find_max_special_sum(arr, k, s):
    max_sum = -float("inf")
    current_sum = 0
    for i, num in enumerate(arr):
        current_sum += num
        if (i < len(arr) - 1):
            continue
        for k in range(1, k+1):
            for s in range(1, max(1, s-1)):
                max_sum = max(max_sum, special_sum(arr[i-k+1:i+1]))
    return max_sum

