def expected_inversions(n):
    inversions = 0

    # Generate all permutations of 1 to k
    for k in range(1, n + 1):
        for perm in product(range(1, k + 1), repeat=k):
            # Count inversions in the permutation
            for i in range(k):
                for j in range(i, k):
                    if perm[i] > perm[j]:
                        inversions += 1

    # The expected number of inversions
    expected = inversions * 1.0 / (n * math.factorial(n))
    return expected

