def find_good_sequences(sequence):
    # Initialize sequence with one element
    pq = deque([sequence])

    result = [0]
    for i in range(len(sequence) - 1):
        current_pq = deque()
        while pq:
            current_sequence = pq.popleft()
            small_left = smallest_good(starting_sequence=current_sequence[:i], ending_sequence=current_sequence[i+1:])
            if small_left is not None:
                currently_good = small_left
                while current_pq:
                    current_sequence = current_pq.popleft()
                    small_right = smallest_good(starting_sequence=current_sequence[:i], ending_sequence=current_sequence[i+1:current_sequence.index(currently_good) - i], gap=len(current_pq))
                    if small_right is not None:
                        new_sequence = current_sequence * len(current_pq) * small_right
                        new_pq = deque(new_sequence)
                        new_pq.appendleft(currently_good)
                        pq.extend(new_pq)
                        break
        result.append(greatest_good(current_sequence=sequence, small_sequence=pq.popleft(), large_sequence=deque(sequence) if pq else deque([sequence[0]])))

def smallest_good(starting_sequence, ending_sequence):
