import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def max_special_sum(arr, K, S):
    length = len(arr)
    n_primes = len(prime_factors(K))

    max_sum = float('-inf')

    for start in range(length):
        current_sum = 0
        for end in range(start, length):
            current_sum += arr[end]
            product = math.prod([term for term in arr[start:end+1] if term > 1])
            if is_prime(product):
                current_prime_factor_count = len(prime_factors(product))
                special_sum = (current_sum * (K // product)) * (n_primes - current_prime_factor_count)
                max_sum = max(max_sum, special_sum)

    return max_sum

