        count = 0
        for mid in range(l, r + 1):
            lower = mid - 1 if mid - 1 >= l else l - 1
            upper = mid + 1 if mid + 1 <= r else r
            if max_index[self.permutation[lower]] <= max_index[self.permutation[mid]] <= max_index[self.permutation[upper]]:
                count += 1
