def fib_mod(n: int, mod: int) -> int:
    if n <= 1:
        return (n, mod - 1) if (mod - n) % 2 == 0 else (mod - n, mod - 1)
    a, aa = fib_mod(n - 1, mod)
    b, bb = fib_mod(n - 2, mod)
    k = a * bb - b * aa
    return k % mod

