def find_place_combination(h, A, k):
    lookup = {}
    for i in range(1 << k):
        A_key = pow(A, i, 998244353)
        A_new_key = (i + h * pow(A_key, -1, 998244353 - (998244353 // 2))) % pow(998244353, 2, 998244353)
