def half_occurrences(seq, x, y, mod):
    """
    Finds the number of half-occurrences of a sequence in the range [x, y] modulo mod.
    """
    n = len(seq)
    count = 0
    for i in range(len(seq)):
        frac_less_than = n / (i + 1) < (x - (i == 0)) / n
        if frac_less_than:
            count += 1
        if i >= len(seq) - x:
            if frac_less_than:
                count -= 1
    return count * (y // x) % mod

