def expected_inversions(n, permutation):
    # Create a dictionary to store the positions of each element in the permutation
    position_dict = {value: index for index, value in enumerate(permutation)}

    expected_inversions = 0

    # Calculate the expected number of inversions for each element
    for i in range(n):
        for j in range(i + 1, n):
            if j <= position_dict[i] <= n - 1:
                for k in range(i + 1, j + 1):
                    if k >= position_dict[i] and k < position_dict[j]:
                        expected_inversions += Fraction(math.comb(position_dict[k] - position_dict[i] - 1, i - position_dict[i])) / (
                            math.comb(j - i, 2)
                        )

    # Adjust the expected number of inversions for base operations
    for i in range(n):
        inversions = 0
        for j in range(i + 1, n):
            if j >= position_dict[i] and j < i + 1:
                inversions += 1
        expected_inversions -= inversions

