from math import factorial as fact
from collections import Counter

def expected_inversions(n, perm):
    # Count inversions in a segment of length k
    def count_inversions(k, perm):
        c = Counter()
        for i in range(min(k, n-1), -1, -1):
            c[perm[i]-1] -= 1
        for i in range(k, k*2):
            c[perm[i-1]-1] += 1
        for i in range(n-k):
            c[perm[i+k-1]-1] += 1
            c[perm[i+k-2]-1] -= 1
        return c[0], sum(c.values())

    total_inversions = 0
    for l in range(1, len(perm)+1):
        r = n - sum(l - ll for ll in range(l)) + 1
        k = min(n-l, r-l+1)
        amt_k = n(n+1)//2 - k*(k-1)//2
        i, j = count_inversions(k, perm)
        for shift in range(i, j):
            total_inversions += l-shift.sum() * shifting_prob(k-1, shift)
        l.appendleft(' ')
    return total_inversions/len(perm)

def shifting_prob(k, s):
    s = factorial(k) // (fact(k-s) * fact(s))
    l = [i-s for i in range(k+1, k+s+1)]
    w = factoradic(k, s)*factoradic(n-k, factorial(k)-fact(k-s)-fact(s))
    return w * s / l

def factoradic(n, k):
    s = 1
    while k > 0:
        s *= n-k+1
        k -= 1
    s //= k + 1
    return s

def run():
    n = int(input())
    perm = list(map(int, input().split()))
    print(f"{expected_inversions(n, perm):.11f}")

run()
