import math
from collections import defaultdict

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def max_special_sum(arr, k, s):
    n = len(arr)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    max_prime_sum = defaultdict(int)  # defaultdict(tuple) to store the sum of the subarray and its number of distinct prime factors

    # Calculate all prefix sums modulo k 
    prefix_sum = [0] * (n + 1)
    prefix_sum[0] = arr[0]
    for i in range(1, n):
        prefix_sum[i] = prefix_sum[i-1] + arr[i]

        # Calculate the number of distinct prime factors of the product of a subarray
        prime_factors_sum = sum([factors(i) for i in prefix_sum[i]: is_prime(i)])

        max_prime_sum[(prefix_sum[i] % k, prime_factors_sum)] = (prefix_sum[i], prefix_sum[i] % k, prime_factors_sum) 

    max_prime_sum[(0, 0)] = (0, 0, 0)

    # Iterate through all possible subarrays
    max_special_sum = 0
    for i in range(1, n + 1):
        for j in range(i):
            special_sum = k * (prefix_sum[i] - prefix_sum[j])
            prime_factors_sum = sum([factors(x) for x in special_sum : is_prime(x)])

            if (special_sum % k, prime_factors_sum) != (0, 0):
                max_prime_sum[(special_sum % k, prime_factors_sum)] = (special_sum, special_sum % k, prime_factors_sum)

                # Update maximum special sum
                if special_sum > max_special_sum:
                    max_special_sum = special_sum 

    return max_special_sum

# Function to get number of distinct prime factors
def factors(num):
    count = 0
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            count += 1

        # Check if i is prime
        while num % i == 0:
            num //= i

        if num == 1:
            break

    # If num is prime and not already accounted for
    if num > 1:
        count += 1

    return count

if __name__ == "__main__":
    n, k, s = map(int, input().split())
    arr = list(map(int, input().split()))

    result = max_special_sum(arr, k, s)
    print(result)
