def cost(t):
    return sum((j - i) for i, j in zip(*sorted(set(t), key=lambda x: x[0])))

def min_cost_partition(arr, k):
    n, m = len(arr), [float('inf') for _ in range(k + 1)]
    cache = {}

    def dp(i, last_max_index, k1):
        if (i, last_max_index, k1) in cache:
            return cache[(i, last_max_index, k1)]
        if i == n:
            return 0
        result = float('inf')
        for j in range(k + 1):
            if j != k1:
                if i == arr[j] - 1:
                    result = min(result, cost(arr[:i + 1][:j]) + dp(i + 1, j, k1 - 1))
                else:
                    result = min(result, dp(i + 1, arr[j] - 1, k1))
        cache[(i, last_max_index, k1)] = result
        return result

    return min(dp(i, last_max_index=max(arr) - 1, k1) for i in range(m))

# Example usage
